import React, { useState } from "react";
import { FaUserPlus, FaPlus } from "react-icons/fa";
import "./AddUser.css"; // We will create this CSS file next

function AddUser({ onAddUser, message }) {
  const [newUser, setNewUser] = useState({
    username: "",
    email: "",
    password: "",
    role: "USER",
    enabled: true,
  });

  const handleChange = (e) => {
    const { name, value } = e.target;
    setNewUser(prevState => ({
      ...prevState,
      [name]: value
    }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    onAddUser(e, newUser);
    setNewUser({ username: "", email: "", password: "", role: "USER", enabled: true }); // Reset form after submission
  };

  return (
    <div className="form-container">
      <div className="form-header">
        <FaUserPlus size={30} style={{ marginRight: '10px' }} />
        <h2>Add New User</h2>
      </div>

      {message && (
        <p className={`status-message ${message.includes("success") ? "success" : "error"}`}>
          {message}
        </p>
      )}

      <form onSubmit={handleSubmit} className="form-style">
        <input
          type="text"
          name="username"
          placeholder="Username"
          value={newUser.username}
          onChange={handleChange}
          required
        />
        <input
          type="email"
          name="email"
          placeholder="Email"
          value={newUser.email}
          onChange={handleChange}
          required
        />
        <input
          type="password"
          name="password"
          placeholder="Password"
          value={newUser.password}
          onChange={handleChange}
          required
        />
        <select
          name="role"
          value={newUser.role}
          onChange={handleChange}
        >
          <option value="USER">USER</option>
          <option value="ADMIN">ADMIN</option>
        </select>
        
        <button type="submit">Add User</button>
      </form>
    </div>
  );
}

export default AddUser;
